from openpyxl import load_workbook

file_path = 'nasa_budget_incomplete.xlsx'
wb = load_workbook(file_path)

for sheet_name in wb.sheetnames:
    ws = wb[sheet_name]
    print(f"--- {sheet_name} ---")
    # Check a few random cells for formulas
    for row in ws.iter_rows(min_row=3, max_row=5, min_col=2, max_col=5):
        for cell in row:
            print(f"{cell.coordinate}: {cell.value} (Type: {type(cell.value)})")

